// File: contracts/MemoniumToken.sol


pragma solidity 0.8.28;





error ZeroAddress();
error InvalidWallet();
error WalletsDifferent();
error NotLaunched();
error TradingDisabled();
error BlacklistedAddress();
error ContractBlocked();
error TradeTooSoon();
error ExceedsMaxTransaction();
error ExceedsMaxWallet();
error TaxTooHigh();
error CooldownTooLong();
error DirectETHNotAccepted();
error TransferFailed();
error AlreadyEnabled();
error NoChange();
error InvalidValue();
error ProtectedWallet();

contract MemoniumToken is ERC20, Pausable, Ownable2Step, ReentrancyGuard {
    // Constants
    uint256 private constant TOTAL_SUPPLY = 100_000_000_000 * 10**18; // 100 billion tokens
    uint256 private constant MAX_TX = TOTAL_SUPPLY >> 7;     // ~0.78% using bit shift
    uint256 private constant MAX_WALLET = TOTAL_SUPPLY >> 6; // ~1.56% using bit shift
    uint256 private constant MAX_TAX = 5;                    // 5% maximum tax
    uint256 private constant BOT_BLOCKS = 5;                 // Anti-bot blocks (increased from 3)
    uint256 private constant MAX_COOLDOWN = 300;             // 5 minutes max cooldown

    struct TradeConfig {
        uint256 buyTax;
        uint256 sellTax;
        uint256 tradeCooldown;
        bool tradingEnabled;
        bool inSwap;
    }

    struct WalletState {
        bool isBlacklisted;
        bool isWhitelisted;
        uint256 lastTradeTime;
    }

    // State variables
    address private immutable taxWallet;
    address private immutable communityWallet;
    uint256 private launchTime;
    
    // Combined mapping for wallet states
    mapping(address wallet => WalletState state) private walletStates;
    TradeConfig private tradeConfig;

    // Events (without redundant timestamps)
    event TradingEnabled();
    event WalletBlacklisted(address indexed wallet, bool indexed status);
    event WalletWhitelisted(address indexed wallet, bool indexed status);
    event TaxUpdated(uint256 buyTax, uint256 sellTax);
    event InitialDistribution(address indexed creatorWallet, address indexed communityWallet);
    event TradeCooldownUpdated(uint256 newCooldown);
    event TokenTransfer(address indexed from, address indexed to, uint256 amount, uint256 tax);
    event ConfigUpdated();

    constructor(
        address _communityWallet,
        address _taxWallet
    ) payable ERC20("Memonium", "MNM") Ownable(msg.sender) {
        if(_communityWallet == address(0)) revert ZeroAddress();
        if(_taxWallet == address(0)) revert ZeroAddress();
        if(_communityWallet == _taxWallet) revert WalletsDifferent();
        
        taxWallet = _taxWallet;
        communityWallet = _communityWallet;
        
        TradeConfig storage config = tradeConfig;
        config.buyTax = 2;
        config.sellTax = 2;
        config.tradeCooldown = 30;
        
        // Initial distribution using bit shifting
        _mint(msg.sender, TOTAL_SUPPLY >> 1);
        _mint(_communityWallet, TOTAL_SUPPLY >> 1);
        
        // Cache wallet states for gas optimization
        WalletState storage creatorState = walletStates[msg.sender];
        WalletState storage communityState = walletStates[_communityWallet];
        WalletState storage taxState = walletStates[_taxWallet];
        
        creatorState.isWhitelisted = true;
        communityState.isWhitelisted = true;
        taxState.isWhitelisted = true;
        
        emit InitialDistribution(msg.sender, _communityWallet);
        emit ConfigUpdated();
    }

    function _processTransfer(
        address sender,
        address recipient,
        uint256 amount
    ) private {
        if(sender == address(0)) revert ZeroAddress();
        if(recipient == address(0)) revert ZeroAddress();
        if(amount == 0) revert InvalidValue();
        
        // Cache storage reads
        WalletState storage senderState = walletStates[sender];
        WalletState storage recipientState = walletStates[recipient];
        TradeConfig storage config = tradeConfig;

        // Basic checks
        if(senderState.isBlacklisted || recipientState.isBlacklisted) revert BlacklistedAddress();
        
        // Skip checks for whitelisted addresses
        if (senderState.isWhitelisted || recipientState.isWhitelisted) {
            _transfer(sender, recipient, amount);
            emit TokenTransfer(sender, recipient, amount, 0);
            return;
        }

        // Trading checks
        if(!config.tradingEnabled) revert TradingDisabled();
        
        // Anti-bot checks
        uint256 currentLaunchTime = launchTime;
        if (currentLaunchTime != 0 && block.timestamp <= currentLaunchTime + BOT_BLOCKS) {
            if(recipient.code.length != 0 || sender.code.length != 0) revert ContractBlocked();
        }
        
        // Trade limits checks
        if(block.timestamp <= senderState.lastTradeTime + config.tradeCooldown) revert TradeTooSoon();
        if(amount >= MAX_TX) revert ExceedsMaxTransaction();
        
        uint256 recipientBalance = balanceOf(recipient);
        if(recipientBalance + amount >= MAX_WALLET) revert ExceedsMaxWallet();
        
        // Update last trade time
        senderState.lastTradeTime = block.timestamp;
        
        // Process taxes if needed
        if (!config.inSwap) {
            uint256 taxAmount = _processTax(sender, amount, config);
            amount -= taxAmount;
        }
        
        _transfer(sender, recipient, amount);
        emit TokenTransfer(sender, recipient, amount, 0);
    }

    function _processTax(
        address sender,
        uint256 amount,
        TradeConfig storage config
    ) private returns (uint256) {
        // Unified tax handling for buy/sell using sellTax as main tax
        uint256 taxAmount = (amount * config.sellTax) / 100;
        
        if(taxAmount != 0) {
            config.inSwap = true;
            _transfer(sender, taxWallet, taxAmount);
            config.inSwap = false;
            emit TokenTransfer(sender, taxWallet, taxAmount, config.sellTax);
        }
        
        return taxAmount;
    }

    function transfer(
        address to,
        uint256 amount
    ) public virtual override nonReentrant whenNotPaused returns (bool) {
        _processTransfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) public virtual override nonReentrant whenNotPaused returns (bool) {
        _spendAllowance(from, msg.sender, amount);
        _processTransfer(from, to, amount);
        return true;
    }

    // Owner functions
    function enableTrading() external payable onlyOwner {
        TradeConfig storage config = tradeConfig;
        if(config.tradingEnabled) revert AlreadyEnabled();
        
        config.tradingEnabled = true;
        launchTime = block.timestamp;
        
        emit TradingEnabled();
        emit ConfigUpdated();
    }

    function setTaxes(uint256 newBuyTax, uint256 newSellTax) external payable onlyOwner {
        if(newBuyTax >= MAX_TAX) revert TaxTooHigh();
        if(newSellTax >= MAX_TAX) revert TaxTooHigh();
        
        TradeConfig storage config = tradeConfig;
        if(newBuyTax == config.buyTax && newSellTax == config.sellTax) revert NoChange();
        
        config.buyTax = newBuyTax;
        config.sellTax = newSellTax;
        
        emit TaxUpdated(newBuyTax, newSellTax);
        emit ConfigUpdated();
    }

    function setWalletStatus(
        address wallet, 
        bool blacklistStatus, 
        bool whitelistStatus
    ) external payable onlyOwner {
        if(wallet == address(0)) revert ZeroAddress();
        if(wallet == owner()) revert ProtectedWallet();
        if(wallet == communityWallet) revert ProtectedWallet();
        if(wallet == taxWallet) revert ProtectedWallet();
        
        WalletState storage state = walletStates[wallet];
        bool currentBlacklist = state.isBlacklisted;
        bool currentWhitelist = state.isWhitelisted;
        
        if(currentBlacklist == blacklistStatus && currentWhitelist == whitelistStatus) revert NoChange();
        
        state.isBlacklisted = blacklistStatus;
        state.isWhitelisted = whitelistStatus;
        
        emit WalletBlacklisted(wallet, blacklistStatus);
        emit WalletWhitelisted(wallet, whitelistStatus);
    }

    function setTradeCooldown(uint256 newCooldown) external payable onlyOwner {
        if(newCooldown >= MAX_COOLDOWN) revert CooldownTooLong();
        
        TradeConfig storage config = tradeConfig;
        if(newCooldown == config.tradeCooldown) revert NoChange();
        
        config.tradeCooldown = newCooldown;
        emit TradeCooldownUpdated(newCooldown);
        emit ConfigUpdated();
    }

    function pause() external payable onlyOwner {
        _pause();
    }

    function unpause() external payable onlyOwner {
        _unpause();
    }

    // View functions
    function getTokenInfo() external view returns (
        uint256 totalSupply_,
        uint256 maxTx_,
        uint256 maxWallet_,
        uint256 buyTax_,
        uint256 sellTax_,
        bool tradingEnabled_,
        uint256 tradeCooldown_,
        uint256 timeSinceLaunch_
    ) {
        TradeConfig storage config = tradeConfig;
        uint256 currentLaunchTime = launchTime;
        uint256 currentBuyTax = config.buyTax;
        uint256 currentSellTax = config.sellTax;
        bool isEnabled = config.tradingEnabled;
        uint256 currentCooldown = config.tradeCooldown;

        totalSupply_ = TOTAL_SUPPLY;
        maxTx_ = MAX_TX;
        maxWallet_ = MAX_WALLET;
        buyTax_ = currentBuyTax;
        sellTax_ = currentSellTax;
        tradingEnabled_ = isEnabled;
        tradeCooldown_ = currentCooldown;
        timeSinceLaunch_ = currentLaunchTime != 0 ? block.timestamp - currentLaunchTime : 0;
    }

    function getWalletInfo(address wallet) external view returns (
        bool isBlacklisted_,
        bool isWhitelisted_,
        uint256 lastTrade_,
        uint256 balance_
    ) {
        WalletState storage state = walletStates[wallet];
        isBlacklisted_ = state.isBlacklisted;
        isWhitelisted_ = state.isWhitelisted;
        lastTrade_ = state.lastTradeTime;
        balance_ = balanceOf(wallet);
    }

    receive() external payable {
        revert DirectETHNotAccepted();
    }

    fallback() external payable {
        revert DirectETHNotAccepted();
    }
}
